android.extraProguardRules:
# SmartPlay R8 keep rules (2026-09-29). Everything below is reached by reflection, JNI or a class name in a manifest, which R8 cannot see.
# Our own native modules from android-native/ (MediaPipePose, BluetoothMediaButton, WearSwingBridge, MetaWearables, MetaCaddyVoiceHandler).
-keep class com.smartplaycaddie.** { *; }
-keep class com.smartplaycaddy.** { *; }
# Expo headless app loader: named ONLY in expo-modules-core's manifest meta-data, so R8 deletes it. expo-task-manager's TaskService calls getAppLoader().loadApp() when a background-location event arrives with the app process dead; stripped, that is an NPE (verified missing from the first R8 build, 2026-09-29).
-keep class expo.modules.adapters.react.apploader.** { *; }
# MediaPipe tasks-vision: JNI into libmediapipe_tasks_vision_jni plus protobuf-lite graph configs read reflectively.
-keep class com.google.mediapipe.** { *; }
-keep class * extends com.google.protobuf.GeneratedMessageLite { *; }
-dontwarn com.google.mediapipe.**
-dontwarn com.google.protobuf.**
# react-native-vision-camera ships no consumer rules.
-keep class com.mrousavy.camera.** { *; }
# RevenueCat RN bridge and hybrid mappings (billing).
-keep class com.revenuecat.purchases.react.** { *; }
-keep class com.revenuecat.purchases.hybridcommon.** { *; }
# Sentry RN bridge (io.sentry core ships its own rules).
-keep class io.sentry.react.** { *; }
# Meta Wearables DAT (glasses profile only; absent from store builds).
-keep class com.meta.wearable.** { *; }
-dontwarn com.meta.wearable.**
